import itertools
def slow(a): return sum(1 for k in range(1, len(a) + 1) for c in itertools.combinations(a, k) if all(x < y for x, y in zip(c, c[1:])))
def fast(a):
    cnt = []
    for i, x in enumerate(a): cnt.append(1 + sum(cnt[j] for j in range(i) if a[j] < x))
    return sum(cnt)
result = slow((2, 1, 3))

